        void PcgAmgBeatsPlainCg()
        {
            var A = Poisson2D(24, 24, Allocator.Temp);
            int n = A.M_Rows;
            var b = GenerateOP.floatRandomVec(n, -1f, 1f, 0xB42u);
            float tol = Tol();

            var xCg = new floatN(n, Allocator.Temp);
            for (int i = 0; i < n; i++) xCg[i] = (float)0;
            var cgInfo = Krylov.cg(in A, in b, ref xCg, 8 * n, tol);

            var amg = new floatAMG(in A, out _, Allocator.Temp);
            var M = new floatAMGPreconditioner(in amg);
            var xPc = new floatN(n, Allocator.Temp);
            for (int i = 0; i < n; i++) xPc[i] = (float)0;
            var pcInfo = Krylov.cg(in A, in M, in b, ref xPc, 8 * n, tol);

            Assert.IsTrue(cgInfo.status == IterativeSolveStatus.Converged);
            Assert.IsTrue(pcInfo.status == IterativeSolveStatus.Converged);
            Assert.IsTrue(floatKrylovBatteryOracles.RelResidualBSR(in A, in xCg, in b) <= tol);   // plain CG really solved it
            Assert.IsTrue(floatKrylovBatteryOracles.RelResidualBSR(in A, in xPc, in b) <= tol);
            // AMG preconditioning must cut the iteration count.
            Assert.IsTrue(pcInfo.iterations < cgInfo.iterations);
        }

