        // A K-cycle hierarchy solves standalone (MG.solve iterates the K-cycle).
        void KCycleSolves()
        {
            var A = Poisson2D(24, 24, Allocator.Temp);
            int n = A.M_Rows;
            var b = GenerateOP.floatRandomVec(n, -1f, 1f, 0x4B01u);
            var amg = new floatAMG(in A, KOpts(), out var info, Allocator.Temp);
            Assert.IsTrue(info.Solved);
