            Assert.IsTrue(floatKrylovBatteryOracles.RelResidualBSR(in A, in x, in b) <= Tol());
        }

        // The K-cycle's per-level Krylov acceleration is never worse than the V-cycle: it converges
        // in no more outer cycles (usually fewer) on the same system. n = 48*48 = 2304 >= 2048 ->
        // Allocator.Persistent with explicit Dispose (large-buffer policy).
        void KCycleTighterThanV()
        {
            var A = Poisson2D(48, 48, Allocator.Persistent);
            int n = A.M_Rows;
            var b = GenerateOP.floatRandomVec(n, -1f, 1f, 0x4B02u, Allocator.Persistent);

            var vAmg = new floatAMG(in A, out _, Allocator.Persistent);           // default V-cycle
            var xv = new floatN(n, Allocator.Persistent); for (int i = 0; i < n; i++) xv[i] = (float)0;
            var vInfo = MG.solve(in vAmg, in b, ref xv, 200, Tol());

            var kAmg = new floatAMG(in A, KOpts(), out _, Allocator.Persistent);
            var xk = new floatN(n, Allocator.Persistent); for (int i = 0; i < n; i++) xk[i] = (float)0;
            var kInfo = MG.solve(in kAmg, in b, ref xk, 200, Tol());

            Assert.IsTrue(vInfo.status == IterativeSolveStatus.Converged);
            Assert.IsTrue(kInfo.status == IterativeSolveStatus.Converged);
            Assert.IsTrue(floatKrylovBatteryOracles.RelResidualBSR(in A, in xk, in b) <= Tol());
            Assert.IsTrue(kInfo.iterations <= vInfo.iterations);

            A.Dispose();
            b.Dispose();
            vAmg.Dispose();
            xv.Dispose();
            kAmg.Dispose();
            xk.Dispose();
        }

