    // Managed-thread reject: an AMG preconditioner that is not a fixed SPD operator (asymmetric
    // V-cycle here; a K-cycle likewise) is rejected by Krylov.cg — the preconditioner constructs
    // fine (it is valid for fcg), but cg throws. Single-level (n=9) hierarchy needs no smoother.
    [Test]
    public void AsymmetricCyclePcgRejected()
    {
        int gx = 3, gy = 3, n = gx * gy;
        var bld = new floatBSRBuilder(n, n, 1, 1, Allocator.Temp, 5 * n);
        for (int y = 0; y < gy; y++)
            for (int x = 0; x < gx; x++)
            {
                int i = y * gx + x;
                bld.AddValue(i, i, (float)4);
                if (x > 0) bld.AddValue(i, i - 1, (float)(-1));
                if (x < gx - 1) bld.AddValue(i, i + 1, (float)(-1));
                if (y > 0) bld.AddValue(i, i - gx, (float)(-1));
                if (y < gy - 1) bld.AddValue(i, i + gx, (float)(-1));
            }
        var A = bld.ToBSR(Allocator.Temp);

        var amg = new floatAMG(in A, new AMGOptions { theta = 0, pre = 2, post = 0, coarseMax = 48, maxLevels = 20 }, out var info, Allocator.Temp);
        Assert.IsTrue(info.Solved);
        var M = new floatAMGPreconditioner(in amg);          // constructing is fine
        var rhs = GenerateOP.floatRandomVec(n, -1f, 1f, 0x321u);
        var sol = new floatN(n, Allocator.Temp);
        Assert.Throws<ArgumentException>(() => { Krylov.cg(in A, in M, in rhs, ref sol); });
    }
}
